3. Global Shortcuts
Cmd+K is just the entry point. You also want shortcuts like Cmd+S (Save) or Cmd+B (Toggle Sidebar).
Use a custom hook useKeyboardShortcut:
import { useEffect } from 'react';

function useKeyboardShortcut(key: string, callback: () =&gt; void, meta = false) {
  useEffect(() =&gt; {
    const handler = (event: KeyboardEvent) =&gt; {
      if (event.key === key && event.metaKey === meta) {
        event.preventDefault();
        callback();
      }
    };
    window.addEventListener('keydown', handler);
    return () =&gt; window.removeEventListener('keydown', handler);
  }, [key, callback, meta]);
}

// Usage
function App() {
  useKeyboardShortcut('s', () =&gt; saveProject(), true); // Cmd+S
  return &lt;div&gt;App&lt;/div&gt;;
}
