WebSockets: Full Duplex Communication
WebSockets maintain a persistent connection for bidirectional messaging.

Setting Up a WebSocket Hook
import { useState, useEffect, useRef, useCallback } from 'react';

type WebSocketStatus = 'connecting' | 'open' | 'closed' | 'error';

function useWebSocket(url: string) {
  const [status, setStatus] = useState&lt;WebSocketStatus&gt;('connecting');
  const [messages, setMessages] = useState&lt;any[]&gt;([]);
  const wsRef = useRef&lt;WebSocket | null&gt;(null);

  useEffect(() =&gt; {
    const ws = new WebSocket(url);
    wsRef.current = ws;

    ws.onopen = () =&gt; setStatus('open');
    ws.onclose = () =&gt; setStatus('closed');
    ws.onerror = () =&gt; setStatus('error');

    ws.onmessage = (event) =&gt; {
      const data = JSON.parse(event.data);
      setMessages(prev =&gt; [...prev, data]);
    };

    return () =&gt; {
      ws.close();
    };
  }, [url]);

  const send = useCallback((data: any) =&gt; {
    if (wsRef.current?.readyState === WebSocket.OPEN) {
      wsRef.current.send(JSON.stringify(data));
    }
  }, []);

  return { status, messages, send };
}


Usage: Chat Application
function ChatRoom({ roomId }) {
  const { status, messages, send } = useWebSocket(`wss://api.example.com/chat/${roomId}`);
  const [input, setInput] = useState('');

  const handleSend = () =&gt; {
    if (input.trim()) {
      send({ type: 'message', content: input });
      setInput('');
    }
  };

  return (
    &lt;div className="chat-room"&gt;
      &lt;div className="status"&gt;
        {status === 'open' ? '🟢 Connected' : '🔴 Disconnected'}
      &lt;/div&gt;

      &lt;div className="messages"&gt;
        {messages.map((msg, i) =&gt; (
          &lt;div key={i} className="message"&gt;
            &lt;strong&gt;{msg.user}:&lt;/strong&gt; {msg.content}
          &lt;/div&gt;
        ))}
      &lt;/div&gt;

      &lt;input 
        value={input} 
        onChange={e =&gt; setInput(e.target.value)}
        onKeyPress={e =&gt; e.key === 'Enter' && handleSend()}
      /&gt;
      &lt;button onClick={handleSend}&gt;Send&lt;/button&gt;
    &lt;/div&gt;
  );
}

Server-Sent Events: Simple One-Way Streaming
SSE is perfect when you only need server-to-client updates (dashboards, notifications):
function useServerEvents(url: string) {
  const [data, setData] = useState&lt;any&gt;(null);
  const [error, setError] = useState&lt;Error | null&gt;(null);

  useEffect(() =&gt; {
    const eventSource = new EventSource(url);

    eventSource.onmessage = (event) =&gt; {
      setData(JSON.parse(event.data));
    };

    eventSource.onerror = () =&gt; {
      setError(new Error('Connection lost'));
      eventSource.close();
    };

    return () =&gt; {
      eventSource.close();
    };
  }, [url]);

  return { data, error };
}

// Usage: Live Dashboard
function StockTicker() {
  const { data: stock, error } = useServerEvents('/api/stocks/AAPL');

  if (error) return &lt;div&gt;Connection lost&lt;/div&gt;;
  if (!stock) return &lt;div&gt;Loading...&lt;/div&gt;;

  return (
    &lt;div className="ticker"&gt;
      &lt;span className="symbol"&gt;{stock.symbol}&lt;/span&gt;
      &lt;span className={stock.change &gt; 0 ? 'up' : 'down'}&gt;
        ${stock.price} ({stock.change}%)
      &lt;/span&gt;
    &lt;/div&gt;
  );
}

Optimistic UI Updates
Update the UI immediately, then reconcile with the server response:
function TodoList() {
  const [todos, setTodos] = useState&lt;Todo[]&gt;([]);
  const { send } = useWebSocket('wss://api.example.com/todos');

  const addTodo = (text: string) =&gt; {
    // Create optimistic todo with temp ID
    const optimisticTodo = {
      id: `temp-${Date.now()}`,
      text,
      completed: false,
      isPending: true,
    };

    // Add to UI immediately
    setTodos(prev =&gt; [...prev, optimisticTodo]);

    // Send to server
    send({ type: 'add', text });
  };

  // Handle server confirmation
  useEffect(() =&gt; {
    // When server confirms, replace temp ID with real ID
    // Handle in WebSocket onmessage handler
  }, []);

  return (
    &lt;ul&gt;
      {todos.map(todo =&gt; (
        &lt;li key={todo.id} className={todo.isPending ? 'pending' : ''}&gt;
          {todo.text}
        &lt;/li&gt;
      ))}
    &lt;/ul&gt;
  );
}

Reconnection Strategy
Real-world connections drop. Implement exponential backoff:





stateDiagram-v2
    [*] --&gt; Connecting
    Connecting --&gt; Open: onopen
    Connecting --&gt; Error: onerror
    Open --&gt; Closed: onclose
    Error --&gt; Reconnecting: after delay
    Closed --&gt; Reconnecting: after delay
    Reconnecting --&gt; Connecting: attempt

    note right of Reconnecting
        Exponential backoff:
        1s → 2s → 4s → 8s...
        max 30s
    end note






function useReconnectingWebSocket(url: string) {
  const [status, setStatus] = useState('connecting');
  const reconnectDelay = useRef(1000);

  useEffect(() =&gt; {
    let ws: WebSocket;
    let reconnectTimer: NodeJS.Timeout;

    function connect() {
      ws = new WebSocket(url);

      ws.onopen = () =&gt; {
        setStatus('open');
        reconnectDelay.current = 1000; // Reset delay on success
      };

      ws.onclose = () =&gt; {
        setStatus('reconnecting');
        // Exponential backoff: 1s, 2s, 4s, 8s... max 30s
        reconnectTimer = setTimeout(() =&gt; {
          reconnectDelay.current = Math.min(reconnectDelay.current * 2, 30000);
          connect();
        }, reconnectDelay.current);
      };
    }

    connect();

    return () =&gt; {
      clearTimeout(reconnectTimer);
      ws?.close();
    };
  }, [url]);

  return status;
}

Feature Flags: Deploy != Release
Feature flags decouple deployment (code goes to production) from release (users see it).

Simple Implementation
// featureFlags.ts
type FeatureFlags = {
  newCheckout: boolean;
  darkMode: boolean;
  aiAssistant: boolean;
};

const flags: FeatureFlags = {
  newCheckout: process.env.ENABLE_NEW_CHECKOUT === 'true',
  darkMode: true,
  aiAssistant: false,
};

export function useFeatureFlag&lt;K extends keyof FeatureFlags&gt;(key: K): boolean {
  return flags[key];
}


Usage
function CheckoutPage() {
  const useNewCheckout = useFeatureFlag('newCheckout');

  return useNewCheckout ? &lt;NewCheckout /&gt; : &lt;LegacyCheckout /&gt;;
}


